@Composable
fun UrduLogoCanvas(
    modifier: Modifier = Modifier,
    color: Color = AppColor
) {
    val composePaths = remember<List<Path>> {
        listOf(
            PathParser().parsePathString(URDU_CALLIGRAPHY_MAIN).toPath(),
            PathParser().parsePathString(URDU_CALLIGRAPHY_DOT_1).toPath(),
            PathParser().parsePathString(URDU_CALLIGRAPHY_DIACRITIC).toPath(),
            PathParser().parsePathString(URDU_CALLIGRAPHY_DOT_2).toPath(),
            PathParser().parsePathString(URDU_CALLIGRAPHY_STROKE_ALIF).toPath()
        )
    }

    Canvas(modifier = modifier) {
        // Viewport bounds corresponding to ONLY the "اردu" Calligraphy mark (X: 10..60, Y: 5..36)
        val minX = 10f
        val minY = 5f
        val calligWidth = 50f
        val calligHeight = 31f

        val scaleX = size.width / calligWidth
        val scaleY = size.height / calligHeight

        scale(scaleX, scaleY, pivot = Offset.Zero) {
            composePaths.forEach { composePath ->
                drawPath(
                    path = composePath,
                    color = color
                )
            }
        }
    }
}
